<script setup lang="ts">
const props=defineProps<{data:any}>()
const {t,locale}=useI18n()
const staff=useStaffStore()
const entryLimits=ref<Record<string,number>>({})
watch(()=>props.data,()=>{entryLimits.value={};expanded.value={}})
const entryKey=(key:string,row:any)=>key+':'+(row.id??'unknown')
const limit=(key:string,row:any)=>entryLimits.value[entryKey(key,row)]||20
const canRead=(key:string)=>staff.hasPermission(key==='supplier'?'asn_read':'dn_read')
const expanded=ref<Record<string,boolean>>({})
const dimensions=['recipient','country','source','supplier'] as const
const rows=(key:string)=>props.data[key]||[]
const max=(key:string)=>Math.max(1,...rows(key).map((row:any)=>row.quantity))
const others=(key:string)=>rows(key).slice(5).reduce((n:number,row:any)=>n+row.quantity,0)
</script>
<template><section class="goods-flows"><h3>{{t('goods-trend.flows')}}</h3><p>{{t('goods-trend.flow-totals',{outbound:data.outbound,inbound:data.inbound,adjustment:data.adjustment_gain})}}</p><div class="panels"><section v-for="key in dimensions" :key="key"><h4>{{t('goods-trend.flow-'+key)}}</h4><p v-if="!rows(key).length">{{t('common.status.nothing-show')}}</p><div v-for="row in expanded[key]?rows(key):rows(key).slice(0,5)" :key="row.id??'unknown'" class="flow-row"><span class="name">{{row.name||t('goods-trend.unrecorded')}}</span><b>{{row.quantity}}</b><small v-if="key==='supplier'">{{t('goods-trend.punctuality',{documents:row.documents,dated:row.dated_documents,rate:row.on_time_rate==null?'—':Number(row.on_time_rate).toLocaleString(locale,{style:'percent',maximumFractionDigits:1})})}}</small><span class="track" aria-hidden="true"><i :style="{width:row.quantity/max(key)*100+'%'}"/></span><details v-if="row.entries?.length" class="documents"><summary>{{t('goods-trend.flow-documents',{count:row.entries.length})}}</summary><p>{{t('goods-trend.flow-document-hint')}}</p><div v-for="(entry,index) in row.entries.slice(0,limit(key,row))" :key="entry.id??index" class="document"><NuxtLink v-if="entry.id&&canRead(key)" :to="`/${key==='supplier'?'asn':'dn'}/detail/${entry.id}`">{{key==='supplier'?'ASN':'DN'}}{{entry.id}}<small v-if="entry.order_number">{{entry.order_number}}</small></NuxtLink><span v-else>{{entry.id?`${key==='supplier'?'ASN':'DN'}${entry.id}`:t('goods-trend.unrecorded')}}</span><b>{{entry.quantity}}</b></div><WButton v-if="row.entries.length>limit(key,row)" size="sm" variant="text" @click="entryLimits[entryKey(key,row)]=limit(key,row)+20">{{t('goods-trend.more-documents')}}</WButton></details></div><template v-if="rows(key).length>5"><p v-if="!expanded[key]">{{t('goods-trend.others',{count:rows(key).length-5,quantity:others(key)})}}</p><WButton size="sm" variant="text" @click="expanded[key]=!expanded[key]">{{t(expanded[key]?'goods-trend.collapse':'goods-trend.show-all')}}</WButton></template></section></div><p>{{t('goods-trend.flow-hint')}}</p></section></template>
<style scoped>
.goods-flows{display:flex;flex-direction:column;gap:12px;border-top:1px solid var(--w-line);padding-top:16px}h3{margin:0;font-size:16px;line-height:24px;font-weight:600}h4{margin:0 0 12px;font-size:13px;font-weight:600}.panels{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.panels>section{min-width:0}.flow-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 12px;margin-bottom:12px;font-size:13px;line-height:20px}.documents{grid-column:1/-1}.documents summary{cursor:pointer;color:var(--w-pri);padding:4px 0}.documents summary:focus-visible{outline:2px solid var(--w-pri);outline-offset:2px}.document{display:flex;justify-content:space-between;gap:12px;padding:6px 0}.document a,.document>span{min-width:0;overflow-wrap:anywhere}.document a{color:var(--w-pri)}.document small{display:block}.name{overflow-wrap:anywhere}.flow-row small{grid-column:1/-1;color:var(--w-text-3);font-size:12px;line-height:18px}.track{grid-column:1/-1;height:6px;background:var(--w-line);border-radius:3px;overflow:hidden}.track i{display:block;height:100%;background:var(--w-pri)}b{font-weight:600}p{margin:0;font-size:12px;line-height:18px;color:var(--w-text-3)}@media(max-width:1000px){.panels{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){.panels{grid-template-columns:minmax(0,1fr)}}
</style>
